package org.marketreview.nativeapp;
import org.json.*;
import java.util.*;
import java.math.*;
import static org.marketreview.nativeapp.WatchlistWorkspaceModel.object;

final class DecisionPacket {
 static String text(Object v,int max){String s=ExternalResearchBatch.trim(v instanceof String?(String)v:"");return s.substring(0,Math.min(s.length(),max));}
 static String code(Object v)throws Exception{String s=(v instanceof Number?LegacyResearchJson.number(((Number)v).doubleValue()):v instanceof String?(String)v:"").replaceAll("[^0-9]","");return s.length()<=6?("000000"+s).substring(s.length()):"";}
 static JSONArray array(JSONObject o,String k){JSONArray a=o.optJSONArray(k);return a==null?new JSONArray():a;}
 static JSONObject obj(JSONObject o,String k){JSONObject v=o.optJSONObject(k);return v==null?new JSONObject():v;}
 static JSONArray head(JSONArray a,int n)throws Exception{JSONArray out=new JSONArray();for(int i=0;i<Math.min(a.length(),n);i++)out.put(a.get(i));return out;}
 static double round2(double n){return new BigDecimal(n).setScale(2,RoundingMode.HALF_UP).doubleValue();}
 static JSONArray latest(JSONArray entries,String dataset)throws Exception{JSONArray valid=new JSONArray(),out=new JSONArray();for(int i=0;i<entries.length();i++){JSONObject e=entries.getJSONObject(i),r=obj(e,"result");if(Boolean.TRUE.equals(e.opt("valid"))&&r.length()>0&&r.opt("dataManifest") instanceof JSONObject)valid.put(e);}if(dataset.isEmpty()&&valid.length()>0)dataset=valid.getJSONObject(0).getJSONObject("result").getJSONObject("dataManifest").optString("datasetId");Set<String>seen=new HashSet<>();for(int i=0;i<valid.length();i++){JSONObject e=valid.getJSONObject(i),r=e.getJSONObject("result");String model=r.optString("modelId");if(!dataset.isEmpty()&&!dataset.equals(r.getJSONObject("dataManifest").optString("datasetId"))||!seen.add(model))continue;out.put(e);}return out;}
 static double numeric(Object v){if(v==JSONObject.NULL)return 0;if(v instanceof Boolean)return (Boolean)v?1:0;if(v instanceof Number)return ((Number)v).doubleValue();if(v instanceof String){String s=ExternalResearchBatch.trim((String)v);if(s.isEmpty())return 0;try{return Double.parseDouble(s);}catch(NumberFormatException e){return Double.NaN;}}return Double.NaN;}
 static void add(Map<String,JSONObject>map,JSONObject source,JSONArray rows)throws Exception{
  JSONArray items=head(rows,30);for(int i=0;i<items.length();i++){JSONObject item=items.getJSONObject(i);String id=code(item.opt("code")),name=text(item.optString("name").isEmpty()?id:item.optString("name"),100);if(id.isEmpty()||java.util.regex.Pattern.compile("(^|\\*)ST",java.util.regex.Pattern.CASE_INSENSITIVE).matcher(name).find())continue;if(!map.containsKey(id))map.put(id,object("code",id,"name",name,"signals",new JSONArray(),"profile",new JSONObject(),"contexts",new JSONArray()));double score=numeric(item.opt("score"));JSONObject signal=object("sourceId",source.opt("sourceId"),"sourceLabel",source.opt("sourceLabel"),"sourceType",source.opt("sourceType"),"rank",i+1,"rankPercentile",round2(items.length()<=1?100:100.0*(items.length()-i)/items.length()),"rawScore",Double.isFinite(score)?score:JSONObject.NULL,"asOf",source.optString("asOf"),"datasetId",source.optString("datasetId"),"validationStatus",source.optString("validationStatus").isEmpty()?"context":source.optString("validationStatus"),"trainedThrough",item.optString("modelTrainedThrough").isEmpty()?item.optString("trainedThrough"):item.optString("modelTrainedThrough"));map.get(id).getJSONArray("signals").put(signal);}
 }
 static double consensus(JSONArray signals)throws Exception{if(signals.length()==0)return 0;double sum=0;Set<String>sources=new HashSet<>();for(int i=0;i<signals.length();i++){JSONObject s=signals.getJSONObject(i);sum+=s.getDouble("rankPercentile");sources.add(s.optString("sourceId"));}return round2(sum/signals.length()*.7+Math.min(sources.size(),3)/3.0*30);}
 static JSONObject build(JSONObject input,JSONObject context,JSONObject knowledge,String generatedAt)throws Exception{
  ExternalResearchBatch.stamp(generatedAt);String question=text(input.opt("question"),1000);if(question.isEmpty())question="综合当前量化模型、因子、专家资料和资讯，哪些股票值得继续研究？";String risk=input.optString("riskProfile");if(!Arrays.asList("conservative","balanced","aggressive").contains(risk))risk="balanced";double max=numeric(input.opt("maxCandidates"));if(!Double.isFinite(max)||max==0)max=12;int limit=(int)Math.min(Math.max(max,3),20);String dataset=text(input.opt("datasetId"),100);JSONArray quant=latest(head(array(context,"quantEntries"),50),dataset);if(dataset.isEmpty()&&quant.length()>0)dataset=quant.getJSONObject(0).getJSONObject("result").getJSONObject("dataManifest").optString("datasetId");JSONObject factor=new JSONObject(),screener=obj(context,"screener");JSONArray factors=head(array(context,"factorEntries"),30);for(int i=0;i<factors.length();i++){JSONObject e=factors.getJSONObject(i),r=obj(e,"result");if(Boolean.TRUE.equals(e.opt("valid"))&&r.length()>0&&(dataset.isEmpty()||dataset.equals(obj(r,"dataManifest").optString("datasetId")))){factor=e;break;}}
  Map<String,JSONObject>map=new LinkedHashMap<>();JSONArray sources=new JSONArray();boolean factorSkipped=false;
  for(int i=0;i<quant.length();i++){JSONObject r=quant.getJSONObject(i).getJSONObject("result"),s=object("sourceId",r.opt("runId"),"sourceLabel",r.opt("modelId"),"sourceType","quant-model","asOf",r.opt("asOf"),"datasetId",obj(r,"dataManifest").opt("datasetId"),"validationStatus",r.opt("validationStatus"),"metrics",r.opt("metrics"));sources.put(s);add(map,s,array(r,"candidates"));}
  if(factor.length()>0){JSONObject r=factor.getJSONObject("result"),composite=obj(r,"composite"),admissions=new JSONObject();boolean eligible=false;JSONArray fs=array(r,"factors");for(int i=0;i<fs.length();i++){String a=fs.getJSONObject(i).optString("admission");admissions.put(a,admissions.optInt(a)+1);eligible|=a.equals("candidate");}JSONObject s=object("sourceId",r.opt("runId"),"sourceLabel","验证期加权复合因子","sourceType","factor-lab","asOf",r.opt("asOf"),"datasetId",obj(r,"dataManifest").opt("datasetId"),"validationStatus",r.opt("validationStatus"),"metrics",composite.opt("metrics"),"rankingEligible",eligible,"factorAdmissions",admissions);sources.put(s);if(eligible)add(map,s,array(composite,"candidates"));else factorSkipped=true;}
  if(screener.length()>0&&screener.opt("result") instanceof JSONObject){JSONObject r=screener.getJSONObject("result");String label=screener.optString("taskName");if(label.isEmpty())label=r.optString("strategy");if(label.isEmpty())label="本地筛选";Object sid=screener.opt("id");String id=sid instanceof Number?LegacyResearchJson.number(((Number)sid).doubleValue()):screener.optString("id");JSONObject s=object("sourceId","screener-"+id,"sourceLabel",label,"sourceType","local-screener","asOf",r.optString("createdAt").isEmpty()?screener.optString("createdAt"):r.optString("createdAt"),"validationStatus","context","strategy",r.optString("strategy").isEmpty()?screener.opt("strategy"):r.opt("strategy"));sources.put(s);add(map,s,array(r,"candidates"));}
  JSONArray positions=array(context,"positions"),watchlist=array(context,"watchlist");Set<String>positionCodes=new HashSet<>(),watchCodes=new HashSet<>();for(int i=0;i<positions.length();i++)positionCodes.add(positions.getJSONObject(i).optString("code"));for(int i=0;i<watchlist.length();i++)watchCodes.add(watchlist.getJSONObject(i).optString("code"));if(map.isEmpty()){JSONArray rows=new JSONArray();for(int i=0;i<positions.length();i++)rows.put(positions.get(i));for(int i=0;i<watchlist.length();i++)rows.put(watchlist.get(i));add(map,object("sourceId","portfolio-context","sourceLabel","持仓与自选上下文","sourceType","portfolio-context","validationStatus","context"),rows);}
  Map<String,JSONObject>profiles=new HashMap<>();JSONArray profileRows=array(context,"profiles");for(int i=0;i<profileRows.length();i++){JSONObject p=profileRows.getJSONObject(i);profiles.put(code(p.opt("code")),p);}List<JSONObject>ranked=new ArrayList<>();
  for(JSONObject item:map.values()){String id=item.getString("code");JSONObject p=profiles.getOrDefault(id,new JSONObject());JSONArray signals=item.getJSONArray("signals");Set<String>seen=new HashSet<>();double lo=100,hi=0;for(int i=0;i<signals.length();i++){JSONObject s=signals.getJSONObject(i);seen.add(s.optString("sourceId"));lo=Math.min(lo,s.getDouble("rankPercentile"));hi=Math.max(hi,s.getDouble("rankPercentile"));}item.put("consensusScore",consensus(signals)).put("signalCount",seen.size()).put("modelDisagreement",signals.length()>1?round2(hi-lo):0).put("industry",p.optString("industry")).put("themes",head(array(p,p.opt("themes") instanceof JSONArray?"themes":"tags"),12)).put("boards",head(array(p,"boards"),8)).put("businessSummary",p.optString("businessSummary").isEmpty()?p.optString("businessScope"):p.optString("businessSummary")).put("inPortfolio",positionCodes.contains(id)).put("inWatchlist",watchCodes.contains(id));ranked.add(item);}
  ranked.sort((a,b)->{int c=Double.compare(b.optDouble("consensusScore"),a.optDouble("consensusScore"));if(c!=0)return c;c=Integer.compare(b.optInt("signalCount"),a.optInt("signalCount"));return c!=0?c:a.optString("code").compareTo(b.optString("code"));});JSONArray candidates=new JSONArray();for(int i=0;i<Math.min(limit,ranked.size());i++)candidates.put(ranked.get(i));
  List<String>tokens=new ArrayList<>();tokens.add(question);for(int i=0;i<candidates.length();i++){JSONObject c=candidates.getJSONObject(i);tokens.add(c.getString("code"));tokens.add(c.getString("name"));JSONArray themes=c.getJSONArray("themes");for(int j=0;j<themes.length();j++)tokens.add(themes.getString(j));tokens.add(c.getString("industry"));}List<String>cleaned=new ArrayList<>();for(String t:tokens){String s=text(t,80).toLowerCase(Locale.ROOT);if(s.length()>=2)cleaned.add(s);}JSONArray newsEvidence=new JSONArray();JSONObject news=obj(context,"news");JSONArray newsItems=array(news,"items");for(int i=0;i<newsItems.length();i++){JSONObject n=newsItems.getJSONObject(i);if(n.optString("source").equalsIgnoreCase("WebStock Fallback"))continue;List<String>parts=new ArrayList<>(Arrays.asList(n.optString("title"),n.optString("summary"),n.optString("source")));for(String key:new String[]{"relatedStocks","relatedSectors"}){JSONArray a=array(n,key);for(int j=0;j<a.length();j++)parts.add(a.getString(j));}String hay=String.join(" ",parts).toLowerCase(Locale.ROOT);boolean match=false;for(String t:cleaned)match|=hay.contains(t);if(!match)continue;String key=n.optString("title")+"|"+n.optString("link")+"|"+n.optString("time");newsEvidence.put(object("evidenceId","NEWS-"+ExternalResearchBatch.sha(key).substring(0,12).toUpperCase(Locale.ROOT),"evidenceType","news","title",n.opt("title"),"source",n.opt("source"),"publishedAt",n.opt("time"),"sourceUrl",n.optString("link").equals("#")?"":n.opt("link"),"content",n.optString("summary").isEmpty()?n.opt("title"):n.opt("summary"),"relatedStocks",array(n,"relatedStocks"),"relatedSectors",array(n,"relatedSectors")));if(newsEvidence.length()==12)break;}
  JSONArray evidence=new JSONArray(),knowledgeItems=array(knowledge,"items");for(int i=0;i<knowledgeItems.length();i++){JSONObject k=new JSONObject(knowledgeItems.getJSONObject(i).toString());if(!k.has("evidenceType"))k.put("evidenceType","knowledge");evidence.put(k);}int knowledgeCount=evidence.length();for(int i=0;i<newsEvidence.length();i++)evidence.put(newsEvidence.get(i));evidence=head(evidence,24);
  JSONArray gaps=new JSONArray();Set<String>datasets=new HashSet<>();for(int i=0;i<sources.length();i++){String d=sources.getJSONObject(i).optString("datasetId");if(!d.isEmpty())datasets.add(d);}if(datasets.size()>1)gaps.put("候选来源使用了不同数据集，只能作为并列证据，不能做严格模型优劣比较");if(quant.length()==0)gaps.put("没有可用的量化模型结果");if(factor.length()==0)gaps.put("没有同数据集因子体检结果");else if(factorSkipped)gaps.put("因子体检没有因子通过“候选”门禁，复合排名未计入共识分");if(screener.length()==0)gaps.put("没有已保存的本地筛选任务");String error=text(knowledge.opt("error"),500);if(!error.isEmpty())gaps.put("专家资料库检索失败："+error);else if(knowledgeCount==0)gaps.put("专家资料库没有匹配证据");if(newsEvidence.length()==0)gaps.put("没有匹配且带来源的资讯证据；本地兜底提示未作为外部证据");for(int i=0;i<candidates.length();i++)if(candidates.getJSONObject(i).getString("businessSummary").isEmpty()){gaps.put("部分候选缺少主营业务摘要或营收结构");break;}
  JSONArray ps=new JSONArray(),ws=new JSONArray();for(int i=0;i<positions.length();i++){JSONObject r=positions.getJSONObject(i),c=new JSONObject();for(String k:new String[]{"code","name","quantity","costPrice","finalPnlRate"})if(r.has(k))c.put(k,r.get(k));ps.put(c);}for(int i=0;i<Math.min(watchlist.length(),50);i++){JSONObject r=watchlist.getJSONObject(i),c=new JSONObject();for(String k:new String[]{"code","name","groupName"})if(r.has(k))c.put(k,r.get(k));ws.put(c);}
  JSONObject packet=object("schema","webstock.research.decision-packet.v1","generatedAt",generatedAt,"question",question,"riskProfile",risk,"datasetId",dataset,"dataSources",sources,"candidates",candidates,"evidence",evidence,"evidenceEngine",knowledge.optString("engine","none"),"newsMeta",obj(news,"meta"),"portfolioContext",object("positions",ps,"watchlist",ws),"dataGaps",gaps);packet.put("prompt",DecisionPrompt.build(packet));return packet;
 }
}
